Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = 1, v = \frac{1}{5}$.\\
Suy ra $x = \dfrac{1}{u} = 1$ và $y = \dfrac{1}{v} = 5$. Vậy nghiệm là $(x; y) = \left(1; 5\right)$.
}\end{ex}

\begin{ex}%[9D1H2-6]
Biết hệ phương trình $\begin{cases}
- \dfrac{5 x}{3} - \dfrac{y}{3}=- \dfrac{1}{3} \\ 
        6 x + y=0
\end{cases}$ có một cặp nghiệm là ${(x_{1},y_{1})}$. Tổng $x_{1}+y_{1} $ bằng
\choice
{ \True $5$  }
   {  $3$ }
     { $6$  }
    {  $4$ }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} \frac{1}{3} - \frac{1}{3 v} - \frac{5}{3 u} = 0 \\ \frac{1}{v} + \frac{6}{u} = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = -1, v = \frac{1}{6}$.\\
Suy ra $x = \dfrac{1}{u} = -1$ và $y = \dfrac{1}{v} = 6$. Vậy nghiệm là $(x; y) = \left(-1; 6\right)$.
}\end{ex}

\begin{ex}%[9D1H2-6]
Biết hệ phương trình $\begin{cases}
\dfrac{x}{3} - y=-6 \\ 
        - \dfrac{x}{2} + y=7
\end{cases}$ có một cặp nghiệm là ${(x_{1},y_{1})}$. Tổng $x_{1}+y_{1} $ bằng
\choice
{ \True $-2$  }
   { $-1$  }
     {  $-3$ }
    {  $-4$ }
\loigiai{
Điều kiện $x \ne 0, y \ne 0$. Đặt $u = \dfrac{1}{x}$ và $v = \dfrac{1}{y}$, ta có hệ phương trình bậc nhất:\\
$\begin{cases} 6 - \frac{1}{v} + \frac{1}{3 u} = 0 \\ -7 + \frac{1}{v} - \frac{1}{2 u} = 0 \end{cases}$.\\
Giải hệ bằng phương pháp thế hoặc cộng đại số được $u = - \frac{1}{6}, v = \frac{1}{4}$.\\
Suy ra $x = \dfrac{1}{u} = -6$ và $y = \dfrac{1}{v} = 4$. Vậy nghiệm là $(x; y) = \left(-6; 4\right)$.
}\end{ex}

\begin{ex}%[9D1H2-6]
Biết hệ phương trình $\begin{cases}
2 x + y=-1 \\ 
        - \dfrac{5 x}{4} + \dfrac{3 y}{5}=- \dfrac{11}{2}
\end{cases}$ có một cặp nghiệm là ${(x_{1},y_{1})}$. Tổng $x_{1}+y_{1} $ bằng
\choice
{ \True $-3$  }
   {  $-5$ }
     { $-2$  }
    {  $-4$ }
\loigiai{
Từ phương trình $(1)$ rút $y = - 2 x - 1$, thế vào phương trình $(2)$ thu được phương trình theo $x$: $\frac{49}{10} - \frac{49 x}{20} = 0$.\\
Vậy hệ phương trình có nghiệm duy nhất $(x; y) = (2; -5)$.
}\end{ex}
